import {downloadFile} from './experience.js';
export function initBillingCheckout({billing,dialog,plans,getState,onApproved}){
 const controls=document.createElement('section');controls.className='billing-checkout';controls.hidden=true;controls.innerHTML='<p class="billing-environment"></p><label>E-mail para o pagamento <span>(opcional)</span><input class="checkout-email" type="email" autocomplete="email" maxlength="254" placeholder="seuemail@exemplo.com"></label><button type="button" class="button primary checkout-go">Continuar no Mercado Pago</button><button type="button" class="button outline checkout-check" hidden>Já paguei · verificar confirmação</button><button type="button" class="checkout-save-access" hidden>Guardar acesso da minha compra</button><p class="checkout-status" role="status"></p><small>Para recuperar pelo e-mail, entre em Minha conta antes de pagar. Comprar sem entrar continua disponível: nesse caso, guarde o arquivo de acesso. Informar o e-mail do pagamento não vincula a compra a uma conta.</small>';dialog.append(controls);
 const checkpoint=document.createElement('section');checkpoint.className='checkout-access-checkpoint';checkpoint.hidden=true;checkpoint.setAttribute('aria-labelledby','checkout-access-title');checkpoint.innerHTML='<h3 id="checkout-access-title" tabindex="-1">Antes de criar, guarde seu acesso.</h3><p class="checkout-access-info">Este arquivo permite recuperar sua compra em outro aparelho. Ele é só seu: não envie para quem vai receber o presente.</p><button type="button" class="button primary checkout-access-download">Baixar meu arquivo de acesso</button><p class="checkout-access-status" role="status">Sem este arquivo, se você apagar os dados deste navegador, poderá perder o acesso à edição da compra.</p><button type="button" class="button outline checkout-access-continue">Continuar sem baixar agora</button><small>Você também encontra “Guardar meu acesso” na etapa Conferir e entregar.</small>';controls.append(checkpoint);
 let selected=plans[1],record=null,busy=false,poll=null,notified='',checkpointId='';const status=controls.querySelector('.checkout-status'),go=controls.querySelector('.checkout-go'),check=controls.querySelector('.checkout-check'),backup=controls.querySelector('.checkout-save-access');
 function stop(){clearTimeout(poll);poll=null;}dialog.addEventListener('close',stop);
 function continueApproved(){if(!record||record.status!=='approved'||record.draftId!==getState().draftId||notified===record.id)return;notified=record.id;stop();checkpoint.hidden=true;dialog.close();if(new URLSearchParams(location.search).has('compra'))history.replaceState(null,'',location.pathname+location.hash);const plan=plans.find(p=>p.id===record.planId)||selected,hasDraft=!!(getState().recipient||getState().planId||getState().pages?.length);const preferred=hasDraft?getState().format:getState().checkoutFormat||record.requestedFormat||plan.format,format=billing.config.plans?.[plan.id]?.formats.includes(preferred)?preferred:plan.format;onApproved({...plan,format},record);}
 function inform(){if(!record){checkpoint.hidden=true;return;}check.hidden=record.status!=='pending';backup.hidden=!record.id||record.status==='approved'||!record.accessKey||record.sessionAuth===true;go.hidden=record.status==='approved';checkpoint.hidden=true;if(record.status==='approved'){status.textContent=record.isAdmin?'Acesso administrativo liberado. Nenhuma cobrança foi feita.':'Pagamento confirmado! Seu mimo já pode ser criado e publicado.';if(notified!==record.id&&record.draftId===getState().draftId){stop();if(record.isAdmin){continueApproved();return;}checkpoint.hidden=false;controls.querySelector('.checkout-email').closest('label').hidden=true;const byAccount=record.sessionAuth===true;checkpoint.querySelector('h3').textContent=byAccount?'Sua compra está na sua conta.':'Antes de criar, guarde seu acesso.';checkpoint.querySelector('.checkout-access-info').textContent=byAccount?'Para continuar em outro aparelho, abra Minha conta e entre com o mesmo e-mail. Não é necessário baixar um arquivo de acesso.':'Este arquivo permite recuperar sua compra em outro aparelho. Ele é só seu: não envie para quem vai receber o presente.';checkpoint.querySelector('.checkout-access-download').hidden=byAccount||!record.accessKey;checkpoint.querySelector('small').textContent=byAccount?'Os presentes publicados ficam disponíveis na sua conta. Rascunhos ainda não publicados ficam neste navegador.':'Você também encontra “Guardar meu acesso” na etapa Conferir e entregar.';if(checkpointId!==record.id+':'+byAccount){checkpointId=record.id+':'+byAccount;checkpoint.querySelector('.checkout-access-status').textContent=byAccount?'Acesso vinculado à sua conta. Nenhuma chave de edição será enviada ou baixada.':'Sem este arquivo, se você apagar os dados deste navegador, poderá perder o acesso à edição da compra.';checkpoint.querySelector('.checkout-access-continue').textContent=byAccount?'Continuar criando meu mimo':'Continuar sem baixar agora';if(dialog.open)checkpoint.querySelector('h3').focus();}}}else if(record.status==='failed'){status.textContent='O pagamento não foi aprovado. Você pode tentar novamente no Mercado Pago.';go.textContent='Tentar outro pagamento';}else if(record.status==='revoked'){status.textContent='Este pagamento foi cancelado ou reembolsado. Entre em contato com quem vendeu o presente se precisar de ajuda.';}else status.textContent='Aguardando a confirmação do Mercado Pago. Se pagou com Pix, aguarde alguns instantes.';}
 checkpoint.querySelector('.checkout-access-download').addEventListener('click',()=>{if(!record?.accessKey||record.sessionAuth===true){checkpoint.querySelector('.checkout-access-status').textContent='Acesse esta compra por Minha conta, usando o mesmo e-mail.';return;}try{downloadFile('capimimo-acesso-da-compra.json',billing.backup());checkpoint.querySelector('.checkout-access-status').textContent='Download solicitado. Confira se o arquivo apareceu na pasta Downloads e guarde-o em um lugar seguro.';checkpoint.querySelector('.checkout-access-continue').textContent='Continuar criando meu mimo';}catch{checkpoint.querySelector('.checkout-access-status').textContent='Não foi possível iniciar o download. Tente novamente ou continue e guarde seu acesso na etapa Conferir e entregar.';}});
 checkpoint.querySelector('.checkout-access-continue').addEventListener('click',continueApproved);
 async function refresh(sync=false){if(!record?.id||busy)return;busy=true;check.disabled=true;try{record=await billing.refresh(record,sync);inform();}catch(e){status.textContent=e.message;}finally{busy=false;check.disabled=false;}if(dialog.open&&record?.status==='pending'){stop();poll=setTimeout(()=>refresh(),5000);}}
 function render(){const config=billing.config;controls.hidden=!config.checkoutReady;dialog.querySelector('.order-test').hidden=!!config.checkoutReady;dialog.querySelector('.order-demo-label').textContent=config.admin?.authenticated?'Acesso administrativo · sem cobrança':config.checkoutReady?(config.mode==='test'?'Ambiente de teste · nenhum valor real será cobrado':'Pagamento seguro · Mercado Pago'):'Demonstração · nenhum pagamento será feito';dialog.querySelector('.order-flow').nextElementSibling.hidden=!!config.checkoutReady;controls.querySelector('.billing-environment').textContent=config.mode==='test'?'Você está testando o fluxo. Use somente os dados de teste do Mercado Pago.':'Pix e cartão disponíveis no checkout do Mercado Pago.';if(!controls.hidden){const candidates=[billing.find()].filter(Boolean);record=candidates.find(r=>r.planId===selected.id)||null;go.hidden=false;go.textContent=config.admin?.authenticated?'Continuar como administrador':config.mode==='test'?'Abrir checkout de teste':'Continuar no Mercado Pago';controls.querySelector('.checkout-email').closest('label').hidden=!!config.admin?.authenticated;check.hidden=!record?.id;backup.hidden=!record?.id||!record.accessKey||record.sessionAuth===true;status.textContent='';inform();}}
 async function show(plan){selected=plan;stop();await billing.ready;render();if(record?.id&&dialog.open)await refresh();}
 go.addEventListener('click',async()=>{if(busy)return;const email=controls.querySelector('.checkout-email');if(!email.reportValidity())return;busy=true;go.disabled=true;status.textContent='Preparando seu pagamento…';try{record=await billing.checkout(selected.id,email.value.trim());inform();if(record.checkoutUrl&&record.status!=='approved'){status.textContent='Abrindo o pagamento seguro…';location.assign(record.checkoutUrl);}else if(record.status==='preparing'){status.textContent='Preparando o checkout. Aguarde alguns segundos e tente novamente.';}}catch(e){status.textContent=e.message;}finally{busy=false;go.disabled=false;}});
 check.addEventListener('click',()=>refresh(true));backup.addEventListener('click',()=>{if(!record?.accessKey||record.sessionAuth===true){status.textContent='Acesse esta compra por Minha conta, usando o mesmo e-mail.';return;}downloadFile('capimimo-acesso-da-compra.json',billing.backup());});
 billing.ready.then(()=>{render();const id=new URLSearchParams(location.search).get('compra'),returning=billing.get(id);if(returning){record=returning;selected=plans.find(p=>p.id===record.planId)||selected;document.dispatchEvent(new CustomEvent('billing:resume',{detail:record}));}});
 document.addEventListener('billing:change',()=>{if(dialog.open&&record?.id){const fresh=billing.get(record.id);if(fresh)record=fresh;inform();}});
 return{show,resume(order){record=order;selected=plans.find(p=>p.id===order.planId)||selected;render();record=order;inform();refresh(true);}};
}
